namespace Recipecommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using Recipecommunity.Models;

namespace Recipecommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
San Marzano tomatoes
Fresh mozzarella
Fresh basil
Olive oil
Salt", Steps = "1. Preheat oven to 475°F.
2. Roll out dough on floured surface.
3. Spread crushed tomatoes evenly.
4. Tear mozzarella and distribute.
5. Bake 10-12 minutes until crust is golden.
6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast
Yogurt
Garam masala
Turmeric
Cumin
Tomato sauce
Heavy cream
Garlic
Ginger
Onion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.
2. Grill or broil chicken until charred.
3. Sauté onion, garlic, and ginger.
4. Add tomato sauce and spices.
5. Simmer 15 minutes, add cream.
6. Add chicken pieces, cook 5 more minutes.", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Lettuce
Tomato
Cheddar cheese
Sour cream
Salsa", Steps = "1. Brown ground beef in skillet.
2. Add taco seasoning and water, simmer.
3. Warm tortillas in dry pan.
4. Assemble tacos with beef and toppings.", AverageRating = 4.2, RatingCount = 18 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles
Shrimp or tofu
Egg
Bean sprouts
Green onions
Peanuts
Lime
Fish sauce
Tamarind paste
Sugar", Steps = "1. Soak rice noodles in warm water 30 minutes.
2. Make sauce: tamarind, fish sauce, sugar.
3. Stir-fry protein until cooked.
4. Push aside, scramble egg.
5. Add noodles and sauce, toss.
6. Serve with bean sprouts, peanuts, lime.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate
Butter
Eggs
Sugar
Flour
Vanilla extract", Steps = "1. Melt chocolate and butter together.
2. Whisk eggs and sugar until fluffy.
3. Fold in chocolate mixture.
4. Add flour and vanilla.
5. Pour into greased ramekins.
6. Bake at 425°F for 12 minutes.
7. Invert onto plate, serve immediately.", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 6, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce
Parmesan cheese
Croutons
Caesar dressing
Lemon juice
Garlic
Anchovy paste
Olive oil", Steps = "1. Wash and chop romaine lettuce.
2. Make dressing: whisk garlic, anchovy, lemon, olive oil.
3. Toss lettuce with dressing.
4. Top with parmesan and croutons.", AverageRating = 4.0, RatingCount = 8 },
    };

    private int _nextId = 7;

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

