@page "/recipe/{Id:int}"
@using Recipecommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe")</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe != null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe == null)
    {
        <p>Recipe not found.</p>
    }
    else
    {
        <h1>@Recipe.Title</h1>
        <p class="text-muted">Category: @Recipe.Category</p>

        <div class="mb-4">
            <h3>Rating</h3>
            <p>⭐ @Recipe.AverageRating.ToString("F1") (@Recipe.RatingCount ratings)</p>
            <Recipecommunity.Components.Shared.StarRating RecipeId="@Recipe.Id" />
        </div>

        <div class="mb-4">
            <h3>Ingredients</h3>
            <ul class="list-group">
                @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>

        <div class="mb-4">
            <h3>Steps</h3>
            @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipecommunity.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@using Recipecommunity.Services
@using Recipecommunity.Models
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@Submission.Title</strong>" has been added to the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="@Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Asian">Asian</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Salads">Salads</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Submission.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Submission.Steps" placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. Add wet ingredients." />
            </div>

            <button type="submit" class="btn btn-success" disabled="@(!IsFormValid)">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool Submitted { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(Submission.Title) &&
        !string.IsNullOrWhiteSpace(Submission.Category) &&
        !string.IsNullOrWhiteSpace(Submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(Submission.Steps);

    private void HandleSubmit()
    {
        if (IsFormValid)
        {
            RecipeService.SubmitRecipe(Submission);
            Submitted = true;
        }
    }
}

@rendermode InteractiveServer
@using Recipecommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @if (UserRating > 0)
    {
        <p class="text-success">Thanks! You rated this @UserRating star(s).</p>
    }
    else
    {
        <span>Rate this recipe: </span>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-4" @onclick="() => SubmitRating(star)" title="@star star(s)">
                @(star <= HoverStar ? "★" : "☆")
            </button>
        }
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int UserRating { get; set; }
    private int HoverStar { get; set; }

    private void SubmitRating(int stars)
    {
        UserRating = stars;
        RecipeService.AddRating(RecipeId, stars);
    }
}

